// Tauride Garden data: the AUTHORED PLANTING of the garden (docs/TAURIDE-REMAKE.md, phase T5; plan C4). Hand-authored (NOT generated by tools/tauride/build.mjs), pure data: no imports.
// Every number is a DESIGN value (no planting survey exists): the reference (docs/research/tauride-reference.md) says "old oaks, limes and larches at the borders, the middle is open lawn", the 2016 aerial shows a dark
// canopy belt along the whole fence, lime avenues along the main alleys, groves where OSM maps its 23 wood polygons, open lawns between them and a lighter planting at the shores. The planter (vegetation.js planVegetation)
// reads this file, the ways (data/paths.js), the woods (data/footprints.js GARDEN_GREEN + the facade polygons), the water (height.js GARDEN_SHORE), the furniture (gates, openings, monuments, the fountain, the service lane),
// the bridges (bridges.js plan.keepOut) and the reeds (reeds.js plan), and the ground mask (ground-material.js) takes the planted crowns as its canopy class, so the leaf litter lies under the trees that are there.
// Frame: metres from ORIGIN, +X east, +Z south (-Z is north), the frame of the whole project.

/** The species of the garden as the ENGINE draws them (environment/treegeo.js SPECIES + SPECIES_EXTRA below): `fam` the geometry family, `scale` the instance scale range (the engine scales 0.4 .. 1.4), `leaf` the palette key of LEAF,
 *  `base` the height of the crown's lowest leaf at scale 1 (metres; the minimum y of the LOD0 canopy of the family: tools/tauride/vegetation-test.mjs pins it against the real geometry) - the planter keeps a crown that would hang below
 *  HEAD_CLEAR over a ribbon off the ribbon altogether; `old` = an old tree that keeps off the steeper flanks (KEEP_OUT.slopeOld). The engine has no alder: the alder of the shore is the ash family (an open oval crown) small and dark. */
export const GARDEN_SPECIES = {
  oak:    { fam: 'oak',    scale: [1.0, 1.25], leaf: 'oak',   base: 2.99, old: true },
  oldOak: { fam: 'oak',    scale: [1.2, 1.4],  leaf: 'oak',   base: 2.99, old: true },      // the 7 OSM trees and the solitary oaks of the meadows (plan: scale 1.2-1.4)
  lime:   { fam: 'limeA',  scale: [0.9, 1.2],  leaf: 'lime',  base: 4.04, old: true },
  limeB:  { fam: 'limeB',  scale: [0.9, 1.15], leaf: 'lime',  base: 4.04, old: true },      // the twin-stem variant (every third avenue lime)
  larch:  { fam: 'larch',  scale: [0.85, 1.15], leaf: 'larch', base: 3.6, old: true },     // SPECIES_EXTRA: a narrow cone on a clear stem of 3.6 m (fix round 1: was an open tent from 0.9 m up)
  ash:    { fam: 'ash',    scale: [0.85, 1.1], leaf: 'ash',   base: 4.58 },
  maple:  { fam: 'mapleA', scale: [0.9, 1.15], leaf: 'maple', base: 3.32 },
  elm:    { fam: 'elm',    scale: [0.85, 1.1], leaf: 'elm',   base: 5.98 },
  birch:  { fam: 'birchA', scale: [0.9, 1.15], leaf: 'birch', base: 3.82 },
  birchB: { fam: 'birchB', scale: [0.9, 1.15], leaf: 'birch', base: 3.71 },
  alder:  { fam: 'ash',    scale: [0.65, 0.85], leaf: 'alder', base: 4.58 },
  shrub:  { fam: 'shrub',  scale: [0.9, 1.4],  leaf: 'shrub', base: 0.13 },
};

/** The garden-local species rows (merged with the engine's SPECIES for the garden only; the strip's buildTrees never sees them): the larch of the border belt, a TALL NARROW cone on a CLEAR STEM, lighter green (the engine's
 *  'tiers' kind with `open` (thin tiers, a fuller cone), `y0` the height of the lowest tier (3.6 m: a walker passes under it, the stem shows), `under` keeps the dark underside of every tier (the tiers read as volumes, not as
 *  paper cut-outs), `stem` the visible trunk [height, foot radius, top radius]. Fix round 1 of T5: the first larch (H 20 / R 3.4, tiers from 0.9 m, no underside) read as a flat tent at 12 m and as a lime-green spruce at 25 m;
 *  the GPU QA asked for a narrower base (R 2.0 .. 2.4), a clear stem of 3 .. 4 m, the underside kept and a less saturated green. trunk = the collision radius at the stem. */
export const SPECIES_EXTRA = {
  larch: { sp: 'larch', H: 21.0, R: 2.4, trunk: 0.45, bark: 'brown', kind: 'tiers', open: true, y0: 3.6, under: true, stem: [4.3, 0.27, 0.16], tiers: [7, 5, 3, 2], seg: [10, 8, 6, 5] },
};

/** leaf colours (sRGB, the per-instance colour; the engine's LEAF table of environment/trees.js is private, these are the same greens for the shared species, plus the larch and the alder) */
export const LEAF = {
  lime: ['#4f7a2e', '#5a8434', '#467028', '#62893a', '#3f6a2a'],
  maple: ['#5e9a35', '#6aa43c', '#548e2f', '#74a840', '#5a9234'],
  elm: ['#4a7430', '#527c36', '#446c2c', '#58803a'],
  ash: ['#5a8a38', '#639240', '#4e7e30', '#6a9a44'],
  oak: ['#4a6e2c', '#53773a', '#42642a', '#5a7e3a'],
  birch: ['#668f3a', '#5e9a35', '#729a42', '#628a38', '#6b9440'],
  larch: ['#6f9a44', '#769f4a', '#68923e', '#7aa44f'],       // lighter and fresher than the broad-leaved crowns (the larch in July), less saturated than the first round's lime green (fix round 1)
  alder: ['#3f6a30', '#466f36', '#3a6230', '#4a7238'],       // dark glossy green
  shrub: ['#52763a', '#5f8641', '#456b32', '#6a9248', '#4e7a3a'],
};

/** THE ZONES (plan C4). Spacings in metres, mixes as weights (normalised by the planter). */
export const ZONES = {
  /** the border belt of old trees INSIDE the fence: the band from `inner` to `width` m inside the garden outline, filled by a jittered lattice of `step` m (the 2016 aerial: a dark canopy along the whole fence, 8-15 m deep), thinning towards its
   *  inner edge from `fadeFrom` m (a soft edge to the lawns), dissolved within KEEP_OUT.gate m of a gate or a fence opening. The perimeter alley runs through the band: the way keep-out keeps the trunks off it and the avenue limes
   *  (planted first) stand in the belt as its lime share. (data/ground.js CANOPY_BELT is the ground's own fallback band for a mask planned without a planting; the planter reads THIS table.) */
  belt: { inner: 1.5, width: 14, fadeFrom: 9, step: 6.5, jitter: 2.6, mix: { oak: 0.4, lime: 0.3, larch: 0.1, ash: 0.1, maple: 0.1 } },
  /** avenues: rows of limes on both sides of every alley of class `classes` (data/paths.js: the long or lit alleys, 3.5-4.5 m), the trunks `offset` m off the ribbon edge (NOT on the ribbon), `spacing` m apart; a way shorter than `minLen` has none */
  avenue: { classes: ['main'], offset: 2.75, spacing: [7.5, 9.5], minLen: 40, endClear: 6, mix: { lime: 0.68, limeB: 0.32 } },
  /** groves on the OSM wood polygons: a jittered lattice of `step` m (`jitter` m) thinned by a slow noise (`clump`: period m, the share kept in the open patches .. in the knots: clearings and dense knots instead of a plantation), `shrub` = the share of candidates that are shrubs instead of trees */
  grove: { step: 9.0, jitter: 4.0, clump: { period: 26, keep: [0.25, 1.0] }, shrub: 0.12, mix: { birch: 0.18, birchB: 0.1, maple: 0.22, lime: 0.22, ash: 0.18, oak: 0.06, elm: 0.04 } },
  /** the open meadows (data/ground.js MEADOWS) stay open: a few solitary old oaks on the big lawns, authored one by one (the T10 meadow, the lake-west lawn, the east strip, the north lobe), each with a clearing of `clear` m that no other tree enters */
  meadow: { clear: 15, solitary: [{ x: 1162, z: -1386 }, { x: 1205, z: -1340 }, { x: 1288, z: -1462 }, { x: 1455, z: -1560 }, { x: 1462, z: -1470 }, { x: 1225, z: -1705 }] },
  /** the shore: alder, birch and shrubs on the CREST band of the banks (from the crest of the bank profile, data/ponds.js BANK_TOP, `d` m inland of it: never on the slope below the crest), walked along the shore rings every `spacing` m */
  shore: { d: [0.3, 2.6], spacing: [8.0, 12.0], mix: { alder: 0.4, birch: 0.25, birchB: 0.1, shrub: 0.25 } },
  /** the 7 mapped OSM trees (data/furniture.js OSM_TREES): old oaks at their mapped positions, planted here and NOT by the environment (HOOKS.treeReject answers 'garden' inside the outline). Every keep-out applies to them;
   *  a node that a rule refuses (the perimeter alley w425201986 runs over three of them: a mapped node sits within the mapping error) is nudged to the NEAREST clear spot within `nudge` m (fix round 2: forced through
   *  the rules, one oak stood on the asphalt of the alley) */
  osm: { species: 'oldOak', nudge: 4 },
};

/** The keep-outs (metres; the trunk axis unless said otherwise). Asserted by tools/tauride/vegetation-test.mjs, each with a mutant (the margin set to 0 plants trees there). */
export const KEEP_OUT = {
  footprint: 3,          // the 13 building footprints (data/footprints.js FOOTPRINTS; the relief's HILL_KEEP_OUT_MARGIN is the same 3)
  way: 1.5,              // every way ribbon (its half width + the ribbon pad of paths-draped.js) + this, measured to the trunk SURFACE (the trunk radius is added)
  headClear: 2.5,        // no leaf lower than this over a ribbon (the walker's head): a crown whose base (GARDEN_SPECIES.base x scale) is lower keeps its whole radius off the ribbon
  bankMargin: 1.0,       // trees of every zone but the shore keep this far inland of the crest of the bank (the bank profile of data/ponds.js: the slope and the crest fall); the shore zone stands on the crest band
  deck: 3,               // the extended deck rectangles of the bridges (bridges.js plan.keepOut) + this
  head: 5,               // the 12 axis ends of the six crossing sites (the bridge heads)
  dam: 5,                // the dam axis
  stair: 4,              // the 6 steps ways (the memorial descents, the wooden bridge's steps), the whole way
  reed: 1,               // every reed clump (reeds.js plan)
  pose: 4,               // the camera poses (CLEARINGS) + a look corridor (len / hw)
  play: 3,               // the pitch, the 3 playgrounds, the fitness station (data/footprints.js GARDEN_GREEN.others)
  fountain: 14,          // the fountain (data/furniture.js FOUNTAINS): T6 builds its plaza
  monument: 8,           // the three monuments (data/furniture.js MONUMENTS)
  memorial: 2,           // the memorial plateau: the ellipse M of data/relief.js grown by this
  gate: 9,               // the 11 gates and the 13 fence openings (data/furniture.js GATES, FENCE_OPENINGS)
  lane: 1.5,             // the service lane (data/furniture.js SERVICE_LANE: 4 m wide) + this
  outline: 1.5,          // the trunk stands this far inside the garden outline (the fence line is T6's)
  slopeOld: 0.18,        // an old tree (GARDEN_SPECIES.old) keeps off ground steeper than this (rise per metre; the relief's limit is 0.25)
  slope: 0.24,           // no tree on ground steeper than this
  water: 0,              // never in the water (the exact shore distance of height.js must be positive); the bank rule above keeps everything off the slope
  pack: 0.55,            // two crowns may overlap down to this fraction of the sum of their radii (the engine's `pack` of a lawn tree)
};

/** The orangery site in the north-west corner of the palace grounds (plan C6; T6 may build it): nothing is planted within r of it. It lies OUTSIDE the garden outline (z -1799 is north of the garden's north edge, -1788.5), so no tree of this planter can reach it; listed so that the rule is one line. */
export const ORANGERY = { x: 965, z: -1799, r: 20 };

