/** The budgets (tools/tauride/vegetation-test.mjs, tools/check.mjs): instances per quality tier (the engine's `density` of environment/trees.js: 'low' = the performance tier; 'medium' and 'high' plant the whole plan), the triangles of the
 *  LOD buckets at the page's HERO (every tree at LOD3: what `npm run check:north` counts) and in the middle of the garden (the LOD0 crowns within 42 m, LOD1 to 150 m: the engine's own per-instance cost, ~1,800 triangles for an old
 *  crown at LOD0), the number of instanced meshes (families x LODs x canopy / trunk), the draws (buckets with instances, + the blobs). `tierFactor` is the share of the plan that the performance tier keeps (each tree keeps or goes by
 *  its own hash: the low tier is a SUBSET of the medium one). */
export const BUDGET = { instances: { high: 1150, medium: 1150, low: 800 }, tierFactor: { high: 1, medium: 1, low: 0.68 }, meshesMax: 72, triangles: { hero: 30000, centre: 330000 }, drawsMax: 64, colliders: 1200 };

/** the LOD distances of the engine's trees (environment/trees.js LOD_D, private there; the test pins the numbers against that file's text) */
export const LOD_D = [42, 150, 360];
